import heapq

def merge_topk_shards(shard_lists: list[list[tuple[float, str]]], k: int = 100) -> list[tuple[float, str]]:
    if k <= 0:
        raise ValueError('k must be positive')
    min_heap: list[tuple[float, str]] = []
    for entries in shard_lists:
        for score, user_id in entries:
            if len(min_heap) < k:
                heapq.heappush(min_heap, (score, user_id))
            elif score > min_heap[0][0]:
                heapq.heapreplace(min_heap, (score, user_id))
    return sorted(min_heap, key=lambda x: x[0], reverse=True)
